#!/usr/bin/env bash
# Bundle item 204 law30_post_video (thread "Videos: Law and Justice committee meetings", 23 Nov 2569, asked by the 3x-daily routine).
# Adds the AFTER-meeting video of Law and Justice main meeting 30/2569 (Wed 18 Nov 2569, 14.00, room 401) to
# parliamentx.com/law/2569/ next to its live BEFORE-meeting video (v30pre, kept as it is, shown first).
# Source: สรุปผลการประชุม ครั้งที่ 30/2569 (สรุปข่าว 30-2569.pdf, ref 11236372, Rpublic=1). 1080x1920, Thai voice + English subtitles
# burned in (one version), kind="post", 2:25. Complaints shown as a count only (2), no names; legal check STOP 0.
# SELF-CONTAINED (shared folder over its cap): mp4/vtt/poster + media.json embedded below as base64 tar.gz.
# Surgical: on DATA key "30|2026-11-18" of law/2569/index.html and meetings.json it keeps every live "pre" video and puts this "post"
# video after it (replacing an older "post" entry if any); fills CAPS track "30"; refreshes the home newest-4 video list and the
# Law 2569 snapshot "v" count (same rules as items 41/62); makes share page s/v-30.html (video_share.py, CARD_BIG=1), no_video_dl.
# Meant to run after 203 (Law site thread's summary item for meeting 30); order-independent anyway (203 keeps live "media").
# video_offload.py in run_bundle.sh then moves v30.mp4 to a video repo. Idempotent; no git, no network.
set -euo pipefail
: "${HUB:?HUB not set}"; BUILD=${BUILD:-/mnt/project-files/archive/build}
TMPP=$(mktemp -d)
trap 'rm -rf "$TMPP"' EXIT
sed -n '/^__PAYLOAD_BELOW__$/,$p' "$0" | tail -n +2 | base64 -d | tar -xz -C "$TMPP"
PAY="$TMPP/pay"
L="$HUB/law/2569"
for f in index.html meetings.json; do test -f "$L/$f" || { echo "204_law30_post_video: $L/$f missing" >&2; exit 1; }; done
test -f "$HUB/index.html" || { echo "204_law30_post_video: hub index.html missing" >&2; exit 1; }
f=v30; want=145
test -s "$PAY/files/media/$f.mp4" -a -s "$PAY/files/media/$f.th.vtt" || { echo "204_law30_post_video: payload $f missing" >&2; exit 1; }
dur=$(ffprobe -v error -show_entries format=duration -of csv=p=0 "$PAY/files/media/$f.mp4")
python3 -c "import sys; sys.exit(0 if abs(float('$dur')-$want)<1.5 else 1)" || { echo "204_law30_post_video: $f length $dur, expected ~$want s" >&2; exit 1; }
wh=$(ffprobe -v error -select_streams v:0 -show_entries stream=width,height -of csv=p=0 "$PAY/files/media/$f.mp4"); [ "$wh" = "1080,1920" ] || { echo "204_law30_post_video: $f size $wh" >&2; exit 1; }
head -1 "$PAY/files/media/$f.th.vtt" | grep -q '^WEBVTT' || { echo "204_law30_post_video: $f vtt header" >&2; exit 1; }
mkdir -p "$L/media" "$L/img"
(cd "$PAY/files" && find . -type f) | while read -r f; do
  cmp -s "$PAY/files/$f" "$L/$f" || cp -f "$PAY/files/$f" "$L/$f"; cmp -s "$PAY/files/$f" "$L/$f"; done
python3 - "$HUB" "$PAY/media.json" <<'PY'
import json, os, sys
HUB, PJ = sys.argv[1], sys.argv[2]; L = os.path.join(HUB, 'law', '2569')
P = json.load(open(PJ, encoding='utf-8')); KEY, POST = P['KEY'], P['POST']
CMP = dict(ensure_ascii=False, separators=(',', ':'))
ser = lambda a: json.dumps(a, **CMP).replace('</', '<\\/')
dec = json.JSONDecoder(); changed = []
def put(path, text):
    if open(path, encoding='utf-8').read() != text:
        open(path, 'w', encoding='utf-8').write(text); changed.append(os.path.relpath(path, HUB))
def with_post(md):
    v = dict(POST); v['size'] = os.path.getsize(os.path.join(L, v['src']))
    vids = [x for x in ((md or {}).get('videos') or []) if x.get('kind') != 'post']
    assert any(x.get('kind') == 'pre' for x in vids), '204_law30_post_video: meeting 30 has no live pre video (expected v30pre)'
    vids.append(v)
    return {'video': vids[0], 'videos': vids}
def jline(lines, prefix, dumps):
    idx = [i for i, l in enumerate(lines) if l.startswith(prefix)]
    assert len(idx) == 1, f'204_law30_post_video: {prefix} line not found once'
    body = lines[idx[0]][len(prefix):]; val, end = dec.raw_decode(body); tail = body[end:]
    for d in dumps:
        if prefix + d(val) + tail == lines[idx[0]]:
            return idx[0], val, tail, d
    raise SystemExit(f'204_law30_post_video: {prefix} line does not round-trip; not touching it')
p = os.path.join(L, 'index.html'); lines = open(p, encoding='utf-8').read().split('\n')
i, arr, tail, d = jline(lines, 'const DATA=', (ser, lambda a: json.dumps(a, ensure_ascii=False)))
keys = {f"{m['n']}|{m['date']}": m for m in arr}
assert KEY in keys, f'204_law30_post_video: index.html meeting {KEY} not on the page'
keys[KEY]['media'] = with_post(keys[KEY].get('media'))
lines[i] = 'const DATA=' + d(arr) + tail
i, caps, tail, d = jline(lines, 'const CAPS=', (lambda a: json.dumps(a, ensure_ascii=False), ser))
caps[POST['ck']] = open(os.path.join(L, POST['vtt']), encoding='utf-8').read()
lines[i] = 'const CAPS=' + d(caps) + tail
put(p, '\n'.join(lines))
p = os.path.join(L, 'meetings.json'); raw = open(p, encoding='utf-8').read(); ms = json.loads(raw)
fmt = [k for k in (dict(indent=1), dict(), dict(separators=(',', ':'))) if json.dumps(ms, ensure_ascii=False, **k) == raw.rstrip('\n')]
assert fmt, '204_law30_post_video: meetings.json does not round-trip; not touching it'
mk = {f"{m['n']}|{m['date']}": m for m in ms}
assert KEY in mk, f'204_law30_post_video: meetings.json meeting {KEY} missing'
mk[KEY]['media'] = with_post(mk[KEY].get('media'))
put(p, json.dumps(ms, ensure_ascii=False, **fmt[0]) + ('\n' if raw.endswith('\n') else ''))
# home page: newest-4 video list + Law 2569 snapshot "v" counts (same rules as items 41/62)
p = os.path.join(HUB, 'index.html'); t = open(p, encoding='utf-8').read()
mark = 'const HH = '
if t.count(mark) == 1:
    i = t.index(mark) + len(mark); hh, _ = dec.raw_decode(t[i:])
    old_s = ser(hh['videos'])
    assert t.count(old_s) == 1, '204_law30_post_video: home video list text not found once'
    law = []
    for m in ms:
        for v in (m.get('media') or {}).get('videos') or []:
            law.append(dict(n=m['n'], date=m['date'], year=2569, who='กมธ.การกฎหมาย และการยุติธรรม', label=v.get('label') or 'วิดีโอสรุป',
                            dur=v.get('dur', ''), poster='law/2569/' + v['poster'] if v.get('poster') else '',
                            headline='' if m.get('pending') else (m.get('headline') or ''), href=f"law/2569/#read-{m['n']}"))
    seen = {(v['href'], v['poster']) for v in hh['videos']}
    vids = hh['videos'] + [v for v in law if (v['href'], v['poster']) not in seen]
    vids.sort(key=lambda v: v['date'], reverse=True)
    t = t.replace(old_s, ser(vids[:4]), 1)
else:
    print('204_law30_post_video: home page has no HH list (skipped)')
dm = 'const DATA = '
assert t.count(dm) == 1, '204_law30_post_video: home DATA not found once'
j = t.index(dm) + len(dm); hub, _ = dec.raw_decode(t[j:])
nv = {(m['n'], m['date']): len((m.get('media') or {}).get('videos') or []) for m in ms}
for c in hub:
    if c.get('id') != 'law':
        continue
    for y in c.get('years', []):
        if y.get('year') != 2569:
            continue
        for s in y.get('snap') or []:
            want = nv.get((s['n'], s['date']))
            if want is not None and s.get('v') != want:
                a = ser(s); s['v'] = want; b = ser(s)
                assert t.count(a) == 1, f'204_law30_post_video: home snapshot entry {s["n"]} not found once'
                t = t.replace(a, b, 1)
put(p, t)
print('204_law30_post_video: changed', ', '.join(changed) or 'nothing (already applied)')
PY
CARD_BIG=1 python3 "$BUILD/video_share.py" "$L" https://parliamentx.com/law/2569 2569
python3 "$BUILD/no_video_dl.py" "$L/s"
python3 "$BUILD/no_video_dl.py" --check "$L"
for f in v-30 v-30-pre; do test -f "$L/s/$f.html" || { echo "204_law30_post_video: share page s/$f.html missing" >&2; exit 1; }; done
python3 - "$L" <<'PY'
import json, sys
L = sys.argv[1]
m = [m for m in json.load(open(f'{L}/meetings.json', encoding='utf-8')) if (m['n'], m['date']) == (30, '2026-11-18')][0]
k = [v['kind'] for v in m['media']['videos']]
assert k.count('pre') == 1 and k.count('post') == 1 and k.index('pre') < k.index('post'), f'204_law30_post_video: meeting 30 videos {k}'
t = open(f'{L}/index.html', encoding='utf-8').read()
assert '"30":' in [x for x in t.split(';') if 'const VSHARE=' in x][0], '204_law30_post_video: VSHARE missing 30'
assert '"30":"WEBVTT' in t.replace(' ', ''), '204_law30_post_video: CAPS track 30 missing'
print('204_law30_post_video OK')
PY
exit 0
